{
  "hypothesis": "Conservatively splitting occupied packets into finer local combs, followed by exact convolution-mixture line searches, can escape the fixed-support plateau and gain at least 1e-5.",
  "rationale": "The reported gains favor finer coherent combs, while coordinate polishing has stalled. This search tests packet-frequency changes as well as coordinated width and anchoring changes, preserving packet mass and accepting a result only after rescoring with the frozen verifier.",
  "source": "import os
os.environ['OMP_NUM_THREADS'] = '1'
os.environ['OPENBLAS_NUM_THREADS'] = '1'
os.environ['MKL_NUM_THREADS'] = '1'
import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve

PARAMS = {
    'time_fraction': (0.68, 0.5, 0.72),
    'max_trials': (70, 10, 200),
    'support_threshold': (1e-12, 1e-15, 1e-7, 'log'),
}

def construct(params, seed, budget_s, init=None):
    start_time = time.monotonic()
    deadline = start_time + float(budget_s) * params['time_fraction']
    rng = np.random.default_rng(seed)
    if init is None:
        return {'values': [1.0, 0.0, 0.6]}
    if 'values' in init:
        f = np.maximum(np.asarray(init['values'], dtype=np.float64), 0.0)
    else:
        f = np.zeros(int(init['length']), dtype=np.float64)
        for s, v in init['packets']:
            if time.monotonic() >= deadline:
                return init
            f[int(s):int(s)+len(v)] += np.asarray(v)
        f = np.maximum(f, 0.0)
    n = len(f)
    if n < 4 or time.monotonic() >= deadline:
        return init

    def exact(a):
        c = oaconvolve(a, a, mode='full')
        xp = np.linspace(-0.5, 0.5, len(c)+2)
        dx = np.diff(xp)
        y = np.concatenate(([0.0], c, [0.0]))
        l2 = float(np.sum((dx/3.0)*(y[:-1]**2 + y[:-1]*y[1:] + y[1:]**2)))
        return float(l2 / ((np.sum(np.abs(c))/(len(c)+1))*np.max(np.abs(c))))

    base_exact = exact(f)
    best_exact = base_exact
    best = None
    scale = float(np.max(f))
    f = f / scale
    active = f > params['support_threshold']
    edges = np.diff(np.r_[False, active, False].astype(np.int8))
    starts = np.flatnonzero(edges == 1)
    ends = np.flatnonzero(edges == -1)
    if len(starts) > 12000:
        for threshold in (1e-10, 1e-8, 1e-6):
            if time.monotonic() >= deadline:
                return init
            active = f > threshold
            edges = np.diff(np.r_[False, active, False].astype(np.int8))
            starts = np.flatnonzero(edges == 1)
            ends = np.flatnonzero(edges == -1)
            if len(starts) <= 12000:
                break
    if len(starts) > 12000 or len(starts) == 0:
        return init
    count = len(starts)
    widths = ends-starts
    masses = np.array([np.sum(f[s:e]) for s,e in zip(starts, ends)])
    total_mass = float(np.sum(f))
    prefixes = []
    for s,e in zip(starts, ends):
        if time.monotonic() >= deadline:
            return init
        prefixes.append(np.r_[0.0, np.cumsum(f[s:e])])

    def resample(i, width):
        oldw = int(widths[i])
        if width == oldw:
            return f[starts[i]:ends[i]].copy()
        p = prefixes[i]
        coordinates = np.linspace(0.0, float(oldw), width+1)
        indices = np.minimum(coordinates.astype(np.int64), oldw-1)
        values = p[indices] + (coordinates-indices)*(p[indices+1]-p[indices])
        values[-1] = p[-1]
        return np.maximum(np.diff(values), 0.0)

    def make_trial(kind, strength, anchor, phase, split=1):
        boundary = np.empty(count+1, dtype=np.int64)
        boundary[0], boundary[-1] = 0, n
        if count > 1:
            boundary[1:-1] = np.rint(ends[:-1] + anchor*(starts[1:]-ends[:-1])).astype(np.int64)
        g = np.zeros(n, dtype=np.float64)
        if kind == 'random':
            perturb = rng.normal(size=count)
            if count > 4:
                perturb = np.convolve(perturb, np.ones(5)/5, mode='same')
            perturb /= max(1e-12, float(np.max(np.abs(perturb))))
        else:
            perturb = np.sin(phase + np.linspace(0.0, strength if kind == 'wave' else 2*np.pi, count))
        for i in range(count):
            if time.monotonic() >= deadline:
                return None
            s,e = int(starts[i]),int(ends[i])
            lo,hi = int(boundary[i]),int(boundary[i+1])
            w = e-s
            if kind == 'split':
                length = hi-lo
                relative = (s-lo)/max(1,length)
                for j in range(split):
                    if time.monotonic() >= deadline:
                        return None
                    a = lo + (length*j)//split
                    b = lo + (length*(j+1))//split
                    if b <= a:
                        continue
                    nw = max(1, min(b-a, int(round(w*strength/split))))
                    ns = int(round(a + relative*(b-a)))
                    ns = max(a, min(b-nw, ns))
                    z = resample(i,nw)
                    g[ns:ns+nw] += z/split
            else:
                if kind == 'width':
                    multiplier = 1.0 + strength
                    move = phase
                elif kind == 'alternating':
                    multiplier = 1.0 + strength*((-1.0)**i)
                    move = phase
                elif kind == 'random':
                    multiplier = 1.0 + strength*perturb[i]
                    move = phase
                else:
                    multiplier = 1.0
                    move = 0.5
                nw = max(1,min(hi-lo,int(round(w*multiplier))))
                ns = int(round(s + move*(w-nw)))
                if kind == 'wave':
                    spare = min(s-lo,hi-e)
                    ns += int(round(phase*perturb[i]*max(1,spare)))
                ns = max(lo,min(hi-nw,ns))
                g[ns:ns+nw] += resample(i,nw)
        sm = float(np.sum(g))
        if sm <= 0:
            return None
        g *= total_mass/sm
        return g

    fft_length = next_fast_len(2*n-1)
    F = rfft(f, fft_length, workers=1)
    c0 = irfft(F*F, fft_length, workers=1)[:2*n-1].copy()
    sumc = float(np.sum(c0))
    def bilinear(a,b):
        return (2.0*float(np.einsum('i,i->',a,b)) + 0.5*(float(np.einsum('i,i->',a[:-1],b[1:]))+float(np.einsum('i,i->',b[:-1],a[1:]))))/3.0
    q0 = bilinear(c0,c0)
    predicted_best = base_exact

    schedule = []
    for anchor in (0.5,0.0,1.0):
        for k in (2,3):
            schedule.append(('split',1.0,anchor,0.0,k))
    for strength in (0.98,1.02,0.9,1.1):
        schedule.append(('split',strength,0.5,0.0,2))
    for strength in (-0.001,0.001,-0.004,0.004,-0.015,0.015):
        for anch in (0.0,0.5,1.0):
            schedule.append(('width',strength,0.5,anch,1))
    for strength in (0.002,0.01,0.04,-0.01):
        schedule.append(('alternating',strength,0.5,0.5,1))
        schedule.append(('random',strength,0.5,0.5,1))
    while len(schedule) < int(params['max_trials']):
        if time.monotonic() >= deadline:
            break
        strength = float(10**rng.uniform(-3.5,-0.8))
        schedule.append(('random',strength,float(rng.choice([0.0,0.5,1.0])),float(rng.random()),1))

    for kind,strength,anchor,phase,k in schedule[:int(params['max_trials'])]:
        if time.monotonic() + 1.8 >= deadline:
            break
        g = make_trial(kind,strength,anchor,phase,k)
        if g is None or time.monotonic() + 1.3 >= deadline:
            break
        G = rfft(g, fft_length, workers=1)
        cross = irfft(F*G, fft_length, workers=1)[:2*n-1].copy()
        cg = irfft(G*G, fft_length, workers=1)[:2*n-1].copy()
        del G
        d = 2.0*(cross-c0)
        e = cg-2.0*cross+c0
        del cross,cg
        coefficients = (q0, 2*bilinear(c0,d), bilinear(d,d)+2*bilinear(c0,e), 2*bilinear(d,e), bilinear(e,e))
        local_score = predicted_best
        local_alpha = None
        tested = []
        for alpha in (1.0,0.5,0.25,0.125,0.03125,0.0078125):
            if time.monotonic() + 0.8 >= deadline:
                break
            cc = c0 + alpha*d + (alpha*alpha)*e
            peak = float(np.max(np.abs(cc)))
            numerator = coefficients[4]
            for coefficient in coefficients[3::-1]:
                if time.monotonic() >= deadline:
                    break
                numerator = numerator*alpha+coefficient
            score = numerator/(sumc*peak)
            tested.append((score,alpha))
            if score > local_score + 2e-13:
                local_score,local_alpha = score,alpha
        if local_alpha is not None and time.monotonic()+1.0 < deadline:
            center = local_alpha
            for alpha in (max(0.0,center*0.75),min(1.0,center*1.25)):
                if time.monotonic()+0.9 >= deadline:
                    break
                cc = c0+alpha*d+alpha*alpha*e
                numerator = sum(coefficients[j]*(alpha**j) for j in range(5))
                score = numerator/(sumc*float(np.max(np.abs(cc))))
                if score > local_score:
                    local_score,local_alpha = score,alpha
            candidate = (1.0-local_alpha)*f+local_alpha*g
            verified = exact(candidate)
            if verified > best_exact:
                best_exact = verified
                predicted_best = verified
                best = candidate
        del d,e,g
    if best is None:
        return init
    return {'values': best.tolist()}
